-- Catalog manual base price (EPIC-06/US-01): set_manual_base_price + create_product profile seed.
-- Context: TH-02/EPIC-06 slice #9 BE; docs/themes/TH-02-product-pricing/harness/*
-- Depends on: 01_catalog_guided_create.sql, 02_catalog_operational_data.sql, 05_catalog_units.sql
